<?php
function ur_is_batch($b){$rows=json_decode($b['rows_json']??'[]',true)?:[];return !empty($rows[0]['unified_return']);}
function ur_require(){if(!can_action('return_confirm'))throw new Exception('Return receiving access required.');}
function ur_owner($b){ur_require();if(!ur_is_batch($b)||$b['status']!=='Review'||(access_profile()!=='Admin'&&(int)$b['created_by']!==current_user()['id']))throw new Exception('Only the preparer or Admin can change this unposted return batch.');}
function ur_source_label($r){return ($r['source_mode']??'')==='unknown'?'No Original Order Record'.(!empty($r['linked_later'])?' · Linked Later':''):'Matched to Original Order';}
function ur_lookup($platform,$number){$platform=stock_platform($platform);$number=trim((string)$number);if($number===''||mb_strlen($number)>100)throw new Exception('Enter an Order ID / Number, up to 100 characters.');$o=om_ready()?om_find($platform,om_shops()[$platform],$number):null;if($o&&$o['posting']!=='Posted')throw new Exception('Order '.$number.' is registered but not actively dispatched. Review it in Order Monitoring; it cannot be received as an unknown order.');$count=(int)om_query("SELECT COUNT(*) FROM outflows WHERE platform=? AND order_id=? AND type='Order' AND qty>0 AND reversed_by_request IS NULL",[$platform,$number])->fetchColumn();$items=[];$mode='unknown';if($count){$source=cancelled_order_lookup($platform,$number);$number=$source['order'];$mode='original';foreach($source['items'] as $pid=>$item)$items[(int)$pid]=$item;}elseif($o)throw new Exception('No active posted item lines were found. Investigate the original dispatch before receiving.');$signature=hash('sha256',json_encode([$platform,$number,$mode,array_map(fn($i)=>$i['signature'],$items)]));return ['platform'=>$platform,'shop'=>om_shops()[$platform],'order'=>$number,'source_mode'=>$mode,'source_signature'=>$signature,'source_remark'=>$mode==='original'?'Matched to Original Order':'No Original Order Record','items'=>$items];}
function ur_build_rows($input){$platform=stock_platform($input['platform']??'');$date=process_date($input['txn_date']??'');if($date>date('Y-m-d'))throw new Exception('Received date cannot be in the future.');require_open_inventory_date($date);$groups=json_decode((string)($input['orders_json']??'[]'),true,512,JSON_THROW_ON_ERROR);if(!is_array($groups)||!$groups||count($groups)>30)throw new Exception('Enter 1 to 30 orders per platform batch.');$seen=[];$rows=[];
 foreach($groups as $group){if(!is_array($group))throw new Exception('Invalid order group.');$source=ur_lookup($platform,$group['order']??'');$key=mb_strtolower($source['order']);if(isset($seen[$key]))throw new Exception('Order '.$source['order'].' is repeated. Add item lines inside its existing group.');$seen[$key]=true;if(!empty($group['source_signature'])&&!hash_equals($source['source_signature'],(string)$group['source_signature']))throw new Exception('Order source changed. Check Order '.$source['order'].' again.');$items=$group['items']??[];if(!is_array($items)||count($items)>200)throw new Exception('Invalid item lines.');$count=0;foreach($items as $item){if(trim((string)($item['qty']??''))==='')continue;$pid=whole_number($item['product_id']??'','Product / SKU',1);$qty=whole_number($item['qty'],'Received quantity',1);$condition=$item['condition']??'';if(!in_array($condition,['Good Item','Damaged / Leak','For Repackaging'],true))throw new Exception('Choose a valid item condition.');$merge=$source['order'].'|'.$pid.'|'.$condition;$count++;if(isset($rows[$merge])){$rows[$merge]['qty']+=$qty;continue;}$p=om_query('SELECT * FROM products WHERE id=?',[$pid])->fetch();if(!$p)throw new Exception('Choose a valid product.');$rows[$merge]=['row'=>0,'unified_return'=>true,'date'=>$date,'platform'=>$platform,'order'=>$source['order'],'product_id'=>$pid,'item'=>$p['name'],'qty'=>$qty,'condition'=>$condition,'transaction_kind'=>'Return Order','source_mode'=>$source['source_mode'],'source_signature'=>$source['source_signature'],'source_remark'=>$source['source_remark'],'remarks'=>$source['source_remark'],'receipt_reference'=>trim((string)($group['receipt_reference']??'')),'physical_ack'=>false,'not_counted_ack'=>false,'separate_receipt_ack'=>false];}if(!$count)throw new Exception('Order '.$source['order'].': enter at least one received quantity. Blank quantities are not received.');}
 if(!$rows||count($rows)>200)throw new Exception('Use 1 to 200 received item lines.');$rows=array_values($rows);usort($rows,fn($a,$b)=>strcmp($a['order'],$b['order'])?:($a['product_id']<=>$b['product_id'])?:strcmp($a['condition'],$b['condition']));foreach($rows as $i=>&$r)$r['row']=$i+1;unset($r);return $rows;
}
function ur_analysis($b,$verification=true){$rows=json_decode($b['rows_json']??'[]',true)?:[];if(in_array($b['status'],['Posted','Reversed','Cancelled'],true))return ['rows'=>$rows,'errors'=>[],'warnings'=>[],'digest'=>''];$checked=[];$errors=[];$warnings=[];$sources=[];$used=[];$stocks=[];$platform=$rows[0]['platform']??'';try{if($verification)oa_receipt_check($b,$rows);}catch(Throwable $e){$errors[]=$e->getMessage();}
 foreach($rows as $row){$row['errors']=[];unset($row['possible_duplicate']);try{if(empty($row['unified_return'])||$row['platform']!==$platform)throw new Exception('One return batch must use one platform and the unified form.');$row['date']=process_date($row['date']);if($row['date']>date('Y-m-d'))throw new Exception('Received date cannot be in the future.');require_open_inventory_date($row['date']);$qty=whole_number($row['qty'],'Received quantity',1);if($qty>100000000)throw new Exception('Received quantity is too large.');if(!in_array($row['condition'],['Good Item','Damaged / Leak','For Repackaging'],true))throw new Exception('Invalid condition.');if($row['condition']==='For Repackaging')packaging_require();$source=$sources[$row['order']]??=ur_lookup($row['platform'],$row['order']);if($source['source_mode']!==$row['source_mode']||!hash_equals($source['source_signature'],$row['source_signature']))throw new Exception('Original order data changed or is now available. Return to the form and match this order again.');$pid=(int)$row['product_id'];$p=om_query('SELECT * FROM products WHERE id=?',[$pid])->fetch();if(!$p)throw new Exception('Product no longer exists.');if($source['source_mode']==='unknown'&&!(int)$p['active'])throw new Exception('Choose an active product for an unrecorded order.');$row['product_name']=$p['name'];$row['sku']=$p['master_sku'];$row['source_remark']=ur_source_label($row);$row['remarks']=$row['source_remark'].(!empty($row['verification_note'])?'; '.$row['verification_note']:'');$balance=order_return_balance($row['platform'],$row['order'],$pid);$used[$row['order']][$pid]=($used[$row['order']][$pid]??0)+$qty;
 if($source['source_mode']==='original'){$item=$source['items'][$pid]??null;if(!$item)throw new Exception('Product is not part of the original dispatched order.');if($row['date']<$item['latest_date'])throw new Exception('Receipt date cannot precede the original dispatch.');if($used[$row['order']][$pid]>$balance['remaining'])throw new Exception('Received quantity exceeds the remaining returnable '.$balance['remaining'].' pcs.');$row=array_replace($row,$balance);$row['remaining_after']=$balance['remaining']-$used[$row['order']][$pid];}else{$row['remaining_after']='Original order not recorded — verified physical return';if($verification&&empty($row['not_counted_ack']))throw new Exception('Confirm the unrecorded return was not included in Beginning Balance or another receipt.');}
 if($verification){if(empty($row['physical_ack']))throw new Exception('Confirm actual physical receipt.');$row['receipt_reference']=unlinked_return_reference($row['receipt_reference']??'');}
 $prior=om_query('SELECT b.batch_ref FROM posted_returns r JOIN return_batches b ON b.id=r.batch_id WHERE r.platform=? AND r.original_ref=? AND r.product_id=? AND r.qty=? AND r.reversed=0 AND r.batch_id<>? LIMIT 1',[$row['platform'],$row['order'],$pid,$qty,(int)($b['id']??0)])->fetchColumn();if($prior){$row['possible_duplicate']=$prior;$warnings[]='Order '.$row['order'].': similar receipt '.$prior.'. Verify a separate physical parcel.';if($verification&&(empty($row['separate_receipt_ack'])||mb_strlen(trim($row['verification_note']??''))<3))throw new Exception('A similar receipt exists. Confirm a separate parcel and enter a verified reference / explanation.');}$stock=stock_row($pid);$stocks[$pid]=[$stock['current'],$stock['physical'],platform_qty($row['platform'],$pid)];
 }catch(Throwable $e){$row['errors'][]=$e->getMessage();$errors[]='Order '.($row['order']??'?').': '.$e->getMessage();}$checked[]=$row;}
 foreach($checked as &$line)if(($line['source_mode']??'')==='original'&&isset($line['remaining']))$line['remaining_after']=max(0,(int)$line['remaining']-($used[$line['order']][$line['product_id']]??0));unset($line);if(!$checked)$errors[]='No received item lines.';return ['rows'=>$checked,'errors'=>array_values(array_unique($errors)),'warnings'=>array_values(array_unique($warnings)),'digest'=>hash('sha256',json_encode([$b['revision']??1,$checked,$stocks]))];
}
function ur_stage($input,$file=null){ur_require();$rows=ur_build_rows($input);$id=(int)($input['editing_id']??0);$probe=['id'=>$id,'revision'=>1,'status'=>'Review','rows_json'=>json_encode($rows)];$a=ur_analysis($probe,false);if($a['errors'])throw new Exception(implode(' · ',$a['errors']));$nonce=(string)($input['form_nonce']??'');if(!preg_match('/^[a-f0-9]{48}$/D',$nonce))throw new Exception('Reopen the return form.');return process_transaction(function()use($input,$rows,$file,$id,$nonce){$old=$id?return_batch($id,true):null;if($old){ur_owner($old);if(json_decode($old['rows_json'],true)[0]['platform']!==$rows[0]['platform'])throw new Exception('An existing batch cannot change platforms. Create a new return batch.');if((int)$old['revision']!==(int)($input['revision']??0))throw new Exception('Review changed. Reopen it before editing.');}$stored=!empty($file['tmp_name'])?store_upload($file,'return_attachments','UNIFIED'):($old['stored_path']??null);$filename=!empty($file['tmp_name'])?basename($file['name']):($old['filename']??'Unified Manual Inflow');if($old){om_query('UPDATE return_batches SET rows_json=?,stored_path=?,filename=?,revision=revision+1 WHERE id=?',[json_encode($rows),$stored,$filename,$id]);inflow_sync_return_history($id);audit('Edit unified return batch','Return',$old['batch_ref'],'Revalidated form; no stock changed.');return $id;}return return_stage($rows,$filename,$stored,hash('sha256','unified|'.current_user()['id'].'|'.$nonce));});}
function ur_verify($id,$revision,$input){ur_require();return process_transaction(function()use($id,$revision,$input){$b=return_batch($id,true);ur_owner($b);if((int)$b['revision']!==(int)$revision)throw new Exception('Verification changed. Refresh the review.');$rows=json_decode($b['rows_json'],true);foreach($rows as &$r){$key=hash('sha256',$r['order']);$r['receipt_reference']=unlinked_return_reference($input['references'][$key]??'');$r['physical_ack']=!empty($input['physical_ack']);$r['not_counted_ack']=!empty($input['not_counted'][$key]);$r['separate_receipt_ack']=!empty($input['separate'][$key]);$r['verification_note']=trim((string)($input['notes'][$key]??''));$r['verified_at']=date('Y-m-d H:i:s');$r['verified_by']=current_user()['id'];}unset($r);$probe=$b;$probe['revision']++;$probe['rows_json']=json_encode($rows);$a=ur_analysis($probe,true);if($a['errors'])throw new Exception(implode(' · ',$a['errors']));om_query('UPDATE return_batches SET rows_json=?,revision=revision+1 WHERE id=?',[json_encode($a['rows']),$id]);inflow_sync_return_history($id);audit('Verify unified return batch','Return',$b['batch_ref'],'References, received quantities and source matching verified; no stock changed.');return $a;});}
function ur_link_original($id,$number){ur_require();return process_transaction(function()use($id,$number){$b=return_batch($id,true);if(!ur_is_batch($b)||$b['status']!=='Posted'||(access_profile()!=='Admin'&&(int)$b['created_by']!==current_user()['id']))throw new Exception('Only the preparer or Admin can link a posted unified return.');$rows=json_decode($b['rows_json'],true);$selected=array_filter($rows,fn($r)=>$r['order']===$number&&$r['source_mode']==='unknown'&&empty($r['linked_later']));if(!$selected)throw new Exception('No unlinked order selected.');$source=ur_lookup(reset($selected)['platform'],$number);if($source['source_mode']!=='original')throw new Exception('The original dispatched order is not yet recorded.');foreach($selected as $r){$balance=order_return_balance($r['platform'],$number,$r['product_id']);if(empty($source['items'][$r['product_id']])||$balance['returned']>$balance['original'])throw new Exception('Original product / quantity does not match this receipt. Investigate before linking.');}foreach($rows as &$r)if($r['order']===$number&&$r['source_mode']==='unknown'){$r['linked_later']=true;$r['linked_at']=date('Y-m-d H:i:s');$r['linked_by']=current_user()['id'];}unset($r);om_query('UPDATE return_batches SET rows_json=?,revision=revision+1 WHERE id=?',[json_encode($rows),$id]);$o=om_find($source['platform'],$source['shop'],$number);if($o){om_return_sync($source['platform'],$number,$id);om_event($o['id'],null,'Existing physical return linked',['source'=>'Manual Inflow','return_batch_id'=>$id,'reason'=>'Original dispatch became available; existing receipt linked','stock_changed'=>false]);}inflow_sync_return_history($id);audit('Link existing unified receipt','Return',$b['batch_ref'],$source['platform'].' / '.$number.'; no quantity posted again.');});}
function ur_report_source($posted){$rows=json_decode($posted['rows_json']??'[]',true)?:[];foreach($rows as $r)if(hash('sha256','return|'.$posted['batch_id'].'|'.$r['row'])===($posted['dedupe_key']??''))return [!empty($r['unified_return'])?ur_source_label($r):(!empty($r['unlinked_receipt'])?'No Original Order Record':'Matched to Original Order'),$r['receipt_reference']??''];return ['Matched to Original Order',''];}
